// Three propositional predicates over compound IRIs. The
// PopulationLevel scope marker rides via the multi-class data
// header (D52 §12 #8 / ESL §4.5a) — the inductive-type resource
// the compiler emits carries both `is_a InductiveType` (implicit)
// and `is_a stats:PopulationLevel`. The §7.4 epistemic-scope
// check reads the marker and admits population-level
// propositions only when the SampleSet's replication kind
// permits.
//
// `sample_for(s, c)` is the linking predicate that ties a
// statistical-level entity (the SampleSet IRI s) to a domain-level
// entity (the compound IRI c). It has no constructors — relationships
// are admitted on chain by committing a `DeclaredResource` whose
// canonical_proposition IS the `sample_for(...)` application. That
// is what lets the polymorphic bridge in Part C universally
// quantify over `(s, c)` without conflating sample sets with
// compounds.

namespace core   = "urn:eigenius:core";
namespace stats  = "urn:eigenius:measurements";
namespace screen = "urn:eigenius:demo:screen";

data screen:HasLowIC50 : core:string -> Prop, stats:PopulationLevel {
}

data screen:StrongInhibitor : core:string -> Prop, stats:PopulationLevel {
}

data screen:sample_for : core:string -> core:string -> Prop {
}

// Six raw IC50 reads of EIG_0291 against CDK2 on a Kinase-Glo
// plate. Tightly clustered (mean ≈ 85, SD ≈ 4.5) so the one-sample
// t-test against threshold 100 nM rejects H0 cleanly under any
// reasonable α.
//
// The SingleSampleEstimate macro lands the Bundle at the
// (CompleteRandom, Unblocked, NoFactor, BiologicalReplication,
// CrossSectional) product position — D52 §5.4 dispatch table.
// BiologicalReplication is what admits the PopulationLevel-marked
// HasLowIC50 predicate downstream.

namespace reflection = "urn:eigenius:reflection";
namespace stats      = "urn:eigenius:measurements";
namespace screen     = "urn:eigenius:demo:screen";

resource screen:m_eig0291_sampleset : stats:SampleSetResource {
    reflection:source      = "instrument-log:kinase-glo-plate-2026-03-11-confirmatory";
    reflection:observed_at = "2026-03-11T10:18:42Z";

    stats:sample_set_value = stats:SingleSampleEstimate(
        [78.0, 82.0, 85.0, 88.0, 91.0, 86.0],
        BiologicalReplication(),
    );
}

resource screen:m_eig0291_sampleset_trace : reflection:ObservationTrace {
    reflection:resource  = screen:m_eig0291_sampleset;
    reflection:source    = "instrument-log:kinase-glo-plate-2026-03-11-confirmatory";
    reflection:timestamp = "2026-03-11T10:18:42Z";
}

// Impossibility witness for the one-sided p-value path.
//
// D52 §7.1: OneSidedWitnessed(witness_iri) directionality is admissible
// only when a chain-resident ImpossibilityWitness encodes the
// methodological argument that the inverse direction is biologically
// impossible. Here the argument is the Kinase-Glo assay's E_max plateau:
// the inverse-direction tail (mean IC50 above the threshold) is
// excluded a-priori by the assay protocol, so halving the two-sided
// p-value to a one-sided p-value is licensed.
//
// The witness itself is a marker resource — no structural requirements
// beyond `is_a stats:ImpossibilityWitness`. Committing it before the
// SAP makes the IRI resolvable when the SAP's `directionality` slot
// references it.

namespace reflection = "urn:eigenius:reflection";
namespace stats      = "urn:eigenius:measurements";
namespace screen     = "urn:eigenius:demo:screen";

resource screen:witness_kinaseglo_floor : stats:ImpossibilityWitness {
    reflection:declared_by = "methodology:kinase-glo-emax-floor";
    reflection:rationale   = "Kinase-Glo's E_max plateau and the cell-free target panel jointly exclude the inverse direction: mean IC50 cannot biologically be above the assay-class threshold under this protocol. This is the chain-resident proof-of-inverse-direction-impossibility that licenses the one-sided p-value path.";
}

// The StatisticalAnalysisPlan. Its commit triggers D52's AutoOnLoad
// gate which recomputes the claim from the SampleSet's raw reads,
// runs the §7.4 epistemic-scope check (BiologicalReplication admits
// PopulationLevel ✓), emits a Verdict::Holds for the SAP itself, AND
// emits a per-effect `StatisticalAnalysisResult` derivation at
// `{plan_iri}:result:main_effect`.
//
// Two shape changes vs. the original demo:
//
// 1. The SAP carries NO propositional content (no `canonical_proposition`,
//    no `null_hypothesis`, no `alternative_hypothesis`). The verifier
//    derives the proposition mechanically from
//    (dispatch, effect_size, directionality) — see D52 §6. The author
//    no longer asserts the proposition; the institution does. For
//    SingleSampleEstimate + OneSidedWitnessed + Absolute(T) the derived
//    proposition lands on the result derivation as
//    `stats:lt(stats:mean_of(sample_set_iri), T)` — a strictly
//    statistical statement about the sample set's mean.
//
// 2. Directionality is `OneSidedWitnessed(witness_iri)`, citing the
//    methodological witness from the previous cell. The bench problem
//    is naturally directional (IC50 BELOW threshold means strong
//    inhibitor; ABOVE threshold doesn't reduce to a biologically
//    interesting designation). The witness makes that asymmetry
//    chain-citable.
//
// Downstream `DerivedEvidence(...)` cites the result derivation, NOT
// the SAP — see Part C. The SAP itself remains queryable via the
// Verdict resource D52 emits for the AutoOnLoad gate.

namespace reflection = "urn:eigenius:reflection";
namespace stats      = "urn:eigenius:measurements";
namespace screen     = "urn:eigenius:demo:screen";

resource screen:claim_eig0291_lowic50 : stats:StatisticalAnalysisPlan {
    stats:sample_set = screen:m_eig0291_sampleset;

    stats:alpha               = 0.05;
    stats:effect_size         = Absolute(100.0, "nM");
    stats:directionality      = OneSidedWitnessed("urn:eigenius:demo:screen:witness_kinaseglo_floor");
    stats:variance_assumption = WelchUnequal();
    stats:outlier_exclusion   = Identity();
}

// D52's AutoOnLoad gate fired on the StatisticalAnalysisPlan commit and
// emitted a Verdict resource. Find it by querying for a Verdict
// whose verdict_subject points back at the claim IRI.

MATCH "urn:eigenius:institution:Verdict"(?v) {
    "urn:eigenius:institution:verdict_subject":     ?subject,
    "urn:eigenius:institution:verdict_query_class": ?qc,
    "urn:eigenius:core:ctor_name":                  ?ctor
}
WHERE ?subject = "urn:eigenius:demo:screen:claim_eig0291_lowic50"
RETURN [] {
    verdict_iri:    ?v,
    ctor:           ?ctor,
    query_class:    ?qc,
    claim:          ?subject
}

// The universal literature rule. One resource, applied at specific
// compounds via SpecStr in downstream certificates. The
// DeclarationTrace registers it in the evidence index under
// IsDeclaredAs(rule_iri, ∀c. HasLowIC50(c) → StrongInhibitor(c)) —
// the witness the certificate's `spec_str` constructor consumes.

namespace core       = "urn:eigenius:core";
namespace reflection = "urn:eigenius:reflection";
namespace screen     = "urn:eigenius:demo:screen";

resource screen:rule_strong : reflection:DeclaredResource {
    reflection:declared_by = "literature:smith_et_al_2024_3.2";
    reflection:rationale   = "Universal: any compound with low IC50 at this target is a strong inhibitor at the same target.";

    reflection:canonical_proposition = type_expr(
        forall (c : core:string) =>
            screen:HasLowIC50(c) -> screen:StrongInhibitor(c)
    );
}

resource screen:rule_strong_trace : reflection:DeclarationTrace {
    reflection:resource    = screen:rule_strong;
    reflection:declared_by = "literature:smith_et_al_2024_3.2";
    reflection:timestamp   = "2026-04-10T09:00:00Z";
}

// Per-pair sample_for witness.
//
// Declares that the EIG_0291 confirmatory SampleSet IS a
// measurement of compound EIG_0291. Pure relationship fact — no
// methodological reasoning, no statistical content. The lab
// technician knows this at plate-load time; this resource lifts
// the knowledge onto chain so the kernel-checkable certificate
// can cite it via DeclaredEvidence.
//
// One such resource per (sample-set, compound) pair the screening
// campaign cares about. The polymorphic bridge below serves all of
// them uniformly — authoring effort scales linearly with pair count
// but each resource is mechanical to write.

namespace core       = "urn:eigenius:core";
namespace reflection = "urn:eigenius:reflection";
namespace screen     = "urn:eigenius:demo:screen";

resource screen:sample_for_eig0291 : reflection:DeclaredResource {
    reflection:declared_by = "lab-bookkeeping:plate-2026-03-11-confirmatory";
    reflection:rationale   = "The confirmatory SampleSet at urn:eigenius:demo:screen:m_eig0291_sampleset was prepared from compound EIG_0291 — recorded by the assay technician at plate-load time.";

    reflection:canonical_proposition = type_expr(
        screen:sample_for(
            "urn:eigenius:demo:screen:m_eig0291_sampleset",
            "urn:eigenius:demo:screen:EIG_0291"
        )
    );
}

resource screen:sample_for_eig0291_trace : reflection:DeclarationTrace {
    reflection:resource    = screen:sample_for_eig0291;
    reflection:declared_by = "lab-bookkeeping:plate-2026-03-11-confirmatory";
    reflection:timestamp   = "2026-03-11T10:18:42Z";
}

// Polymorphic statistical-to-domain bridge.
//
// One resource for the whole "IC50 < 100 nM ⇒ HasLowIC50"
// methodology. Universally-quantified over (sample_set, compound)
// pairs. The `sample_for(s, c)` premise is what makes the universal
// closure type-sound: without it, the bridge would assert that ANY
// sample set's mean being below threshold implies that ANY compound
// is a low-IC50 inhibitor, which is structurally wrong.
//
// The 100.0 nM threshold rides as a literal in the bridge's identity
// — different thresholds are different bridges. D39's SpecStr is
// string-only, so we can't polymorphise over the float without a
// kernel extension; that's also structurally fine since a different
// threshold IS a different decision rule.
//
// At certificate time, this resource gets specialised at the
// concrete (sample_set, compound) pair via two nested SpecStr
// calls. The cert then App-chains the specialised bridge with the
// sample_for witness, the SAR's DerivedEvidence, and the
// SpecStr-specialised literature rule. See the next cell.

namespace core       = "urn:eigenius:core";
namespace reflection = "urn:eigenius:reflection";
namespace stats      = "urn:eigenius:measurements";
namespace screen     = "urn:eigenius:demo:screen";

resource screen:bridge_lowic50 : reflection:DeclaredResource {
    reflection:declared_by = "methodology:ic50-classification-convention";
    reflection:rationale   = "Universal: for any sample set s drawn from compound c, if s's mean IC50 is statistically below 100 nM, classify c as HasLowIC50 at the assayed target. Methodology + threshold are baked into the bridge's identity.";

    reflection:canonical_proposition = type_expr(
        forall (s : core:string) =>
        forall (c : core:string) =>
            screen:sample_for(s, c)
            -> stats:lt(stats:mean_of(s), 100.0)
            -> screen:HasLowIC50(c)
    );
}

resource screen:bridge_lowic50_trace : reflection:DeclarationTrace {
    reflection:resource    = screen:bridge_lowic50;
    reflection:declared_by = "methodology:ic50-classification-convention";
    reflection:timestamp   = "2026-04-10T09:00:00Z";
}

// The reasoning sentence — five-step composition.
//
//   bridge : ∀ s c, sample_for(s,c) → stats:lt(mean_of(s), 100) → HasLowIC50(c)
//        │  SpecStr at s = confirmatory_sample_set
//        ▼
//   ∀ c, sample_for(s_confirmatory, c) → stats:lt(mean_of(s_confirmatory), 100) → HasLowIC50(c)
//        │  SpecStr at c = EIG_0291
//        ▼
//   sample_for(s_confirmatory, EIG_0291) → stats:lt(mean_of(s_confirmatory), 100) → HasLowIC50(EIG_0291)
//        │  App with DeclaredEvidence(sample_for_witness)
//        ▼
//   stats:lt(mean_of(s_confirmatory), 100) → HasLowIC50(EIG_0291)
//        │  App with DerivedEvidence(SAR)
//        ▼
//   HasLowIC50(EIG_0291)
//        │  App with SpecStr(literature_rule, EIG_0291)
//        ▼
//   StrongInhibitor(EIG_0291)
//
// Justification: nested SpecStr + nested App. The trailing
// ChainWitness slot on each `declared`/`derived` ctor is elided —
// the kernel's synthesize hook fills it from the chain witness
// index at type-check time.
//
// The qualified `reasoning:App(...)` picks the
// `reasoning:JustificationTerm.App` ctor; the bare `App` short name
// collides with `eigentt:TypeExpr.App` and the type_expr parser
// resolves to the TypeExpr ctor otherwise.

namespace core      = "urn:eigenius:core";
namespace reasoning = "urn:eigenius:reasoning";
namespace stats     = "urn:eigenius:measurements";
namespace screen    = "urn:eigenius:demo:screen";

resource screen:concl_eig0291_strong : reasoning:ReasoningSentence {
    reasoning:subject_iri = "urn:eigenius:demo:screen:EIG_0291";

    reasoning:proposition = type_expr(
        screen:StrongInhibitor("urn:eigenius:demo:screen:EIG_0291")
    );

    reasoning:justification = App(
        SpecStr(
            DeclaredEvidence("urn:eigenius:demo:screen:rule_strong"),
            "urn:eigenius:demo:screen:EIG_0291"
        ),
        reasoning:App(
            reasoning:App(
                SpecStr(
                    SpecStr(
                        DeclaredEvidence("urn:eigenius:demo:screen:bridge_lowic50"),
                        "urn:eigenius:demo:screen:m_eig0291_sampleset"
                    ),
                    "urn:eigenius:demo:screen:EIG_0291"
                ),
                DeclaredEvidence("urn:eigenius:demo:screen:sample_for_eig0291")
            ),
            DerivedEvidence("urn:eigenius:demo:screen:claim_eig0291_lowic50:result:main_effect")
        )
    );

    reasoning:certificate = type_expr(
        alias
            EIG    = "urn:eigenius:demo:screen:EIG_0291",
            SS     = "urn:eigenius:demo:screen:m_eig0291_sampleset",
            SAR    = "urn:eigenius:demo:screen:claim_eig0291_lowic50:result:main_effect",
            BRIDGE = "urn:eigenius:demo:screen:bridge_lowic50",
            RULE   = "urn:eigenius:demo:screen:rule_strong",
            SFW    = "urn:eigenius:demo:screen:sample_for_eig0291",

            // Reusable propositions
            STAT    = stats:lt(stats:mean_of(SS), 100.0),
            HAS_LOW = screen:HasLowIC50(EIG),
            STRONG  = screen:StrongInhibitor(EIG),
            S_FOR   = screen:sample_for(SS, EIG),

            // Universal propositions for rule + bridge
            RULE_P   = forall (x : core:string) =>
                          screen:HasLowIC50(x) -> screen:StrongInhibitor(x),
            BRIDGE_P = forall (s : core:string) =>
                       forall (c : core:string) =>
                          screen:sample_for(s, c)
                          -> stats:lt(stats:mean_of(s), 100.0)
                          -> screen:HasLowIC50(c),

            // Justification spine pieces
            rule_j      = SpecStr(DeclaredEvidence(RULE), EIG),
            bridge_s    = SpecStr(DeclaredEvidence(BRIDGE), SS),
            bridge_full = SpecStr(bridge_s, EIG),
            sf_j        = DeclaredEvidence(SFW),
            derived_j   = DerivedEvidence(SAR),
            bridge_app  = reasoning:App(bridge_full, sf_j),
            full_app    = reasoning:App(bridge_app, derived_j)
        in
        app(
            HAS_LOW, STRONG,
            rule_j, full_app,
            // outer c1 : specialise the literature rule at EIG_0291.
            spec_str(
                fun (x : core:string) =>
                    screen:HasLowIC50(x) -> screen:StrongInhibitor(x),
                DeclaredEvidence(RULE),
                EIG,
                declared(RULE, RULE_P)
            ),
            // outer c2 : middle app composes the partially-applied bridge
            // (after sample_for) with the SAR.
            app(
                STAT, HAS_LOW,
                bridge_app, derived_j,
                // middle c1' : inner app composes the fully-specialised
                // bridge with the sample_for witness.
                app(
                    S_FOR, STAT -> HAS_LOW,
                    bridge_full, sf_j,
                    // inner c1'' : nested spec_str specialising the bridge.
                    spec_str(
                        fun (c : core:string) =>
                            screen:sample_for(SS, c)
                            -> stats:lt(stats:mean_of(SS), 100.0)
                            -> screen:HasLowIC50(c),
                        bridge_s,
                        EIG,
                        spec_str(
                            fun (s : core:string) =>
                                forall (c : core:string) =>
                                    screen:sample_for(s, c)
                                    -> stats:lt(stats:mean_of(s), 100.0)
                                    -> screen:HasLowIC50(c),
                            DeclaredEvidence(BRIDGE),
                            SS,
                            declared(BRIDGE, BRIDGE_P)
                        )
                    ),
                    // inner c2'' : the sample_for witness
                    declared(SFW, S_FOR)
                ),
                // middle c2' : the SAR
                derived(SAR, STAT)
            )
        )
    );
}

// D39's AutoOnLoad gate fired on the ReasoningSentence commit and
// emitted a Verdict resource. Find it by subject IRI.

MATCH "urn:eigenius:institution:Verdict"(?v) {
    "urn:eigenius:institution:verdict_subject":     ?subject,
    "urn:eigenius:institution:verdict_query_class": ?qc,
    "urn:eigenius:core:ctor_name":                  ?ctor
}
WHERE ?subject = "urn:eigenius:demo:screen:concl_eig0291_strong"
RETURN [] {
    verdict_iri: ?v,
    ctor:        ?ctor,
    query_class: ?qc,
    sentence:    ?subject
}

// Closure query — both verdicts in one result, with their query
// classes naming which institution fired. Walk the audit chain
// from a single result: each row carries the subject (claim or
// sentence), the institution that endorsed it, and the Holds/Fails
// verdict ctor.

MATCH "urn:eigenius:institution:Verdict"(?v) {
    "urn:eigenius:institution:verdict_subject":     ?subject,
    "urn:eigenius:institution:verdict_query_class": ?qc,
    "urn:eigenius:core:ctor_name":                  ?ctor
}
WHERE ?subject = "urn:eigenius:demo:screen:claim_eig0291_lowic50"
   OR ?subject = "urn:eigenius:demo:screen:concl_eig0291_strong"
RETURN [] {
    subject:     ?subject,
    institution: ?qc,
    verdict:     ?ctor
}
